function trackbatch_export_params(matPath, jsonPath, utrackPath)
%TRACKBATCH_EXPORT_PARAMS Dump the parameters stored in a u-track .mat file to JSON.
%   Handles u-track 2.x movieData.mat (MovieData objects - exports each
%   process's funParams_) and plain result files saved as MATLAB v7.3.
%   Generated by trackbatch.
if nargin > 2 && ~isempty(utrackPath)
    addpath(genpath(utrackPath));
end
s = load(matPath);
skip = {'tracksFinal', 'movieInfo', 'kalmanInfoLink', 'localMaxima', 'background', 'exceptions'};
out = struct();
names = fieldnames(s);
for i = 1:numel(names)
    if any(strcmp(names{i}, skip)), continue; end
    v = s.(names{i});
    if isobject(v) && isprop(v, 'processes_')
        procs = cell(1, numel(v.processes_));
        for p = 1:numel(v.processes_)
            pr = v.processes_{p};
            procs{p} = struct('class', class(pr), 'funParams', sanitize(pr.funParams_));
        end
        out.(names{i}) = struct('processes', {procs});
    else
        out.(names{i}) = sanitize(v);
    end
end
fid = fopen(jsonPath, 'w', 'n', 'UTF-8');
fprintf(fid, '%s', jsonencode(out));
fclose(fid);
end

function v = sanitize(v)
if isa(v, 'function_handle')
    v = func2str(v);
elseif isstruct(v)
    if numel(v) > 1
        c = cell(1, numel(v));
        for k = 1:numel(v), c{k} = sanitize(v(k)); end
        v = c;
        return
    end
    f = fieldnames(v);
    for k = 1:numel(f)
        v.(f{k}) = sanitize(v.(f{k}));
    end
elseif iscell(v)
    for k = 1:numel(v), v{k} = sanitize(v{k}); end
elseif isobject(v)
    v = class(v);
elseif isnumeric(v) && numel(v) > 1000
    v = [];  % large result arrays are not parameters
elseif isnumeric(v)
    v(isinf(v)) = sign(v(isinf(v))) * 1e308;
end
end
